:root {
  --gris-50: #f5f6f8; --gris-600: #5b6270; --gris-900: #14161a;
  --azul-600: #1d5fd1; --azul-300: #8ab4ff; --blanco: #ffffff;
  --fondo: var(--gris-50);
  --superficie: var(--blanco);
  --texto: var(--gris-900);
  --texto-suave: var(--gris-600);
  --accion: var(--azul-600);
  --accion-texto: var(--blanco);
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root {
    --fondo: #0e1014; --superficie: #1b1e24; --texto: #eef0f3;
    --texto-suave: #a3a9b5; --accion: var(--azul-300); --accion-texto: #0e1014;
    color-scheme: dark;
  }
}
body { margin: 0; background: var(--fondo); color: var(--texto); font: 16px/1.4 system-ui, sans-serif; }
main { max-width: 28rem; margin: 0 auto; padding: 1rem; }
header { display: flex; justify-content: space-between; align-items: center; gap: .5rem; }
.tarjeta { background: var(--superficie); border-radius: .75rem; padding: 1rem; margin-top: 1rem; }
.suave { color: var(--texto-suave); }
.barra { height: .5rem; background: var(--fondo); border-radius: .25rem; overflow: hidden; }
.barra > span { display: block; height: 100%; width: 100%; background: var(--accion);
  transform-origin: left; transform: scaleX(var(--avance, 0)); transition: transform .4s ease-out; }
@media (prefers-reduced-motion: reduce) { .barra > span { transition: none; } }
button { background: var(--accion); color: var(--accion-texto); border: 0; border-radius: .5rem;
  min-height: 44px; padding: 0 1rem; font: inherit; }
button:focus-visible { outline: 3px solid var(--texto); outline-offset: 2px; }
ol { list-style: none; padding: 0; margin: .5rem 0 0; display: grid; gap: .25rem; }
li[aria-current="step"] { font-weight: 700; }

// Estado: la verdad de la pantalla
const estado = { cargando: true, error: null, pedido: null };
const oyentes = new Set();
function cambiar(parche) { Object.assign(estado, parche); oyentes.forEach(f => f()); }

// Servidor: un pedido con plazo de 3 s
async function traerPedido() {
  const ac = new AbortController();
  const t = setTimeout(() => ac.abort(), 3000);
  try {
    const r = await fetch('/api/pedidos/AR-1042', { signal: ac.signal });
    if (!r.ok) throw new Error('HTTP ' + r.status);
    cambiar({ cargando: false, error: null, pedido: await r.json() });
  } catch (e) {
    cambiar({ cargando: false, error: 'No pudimos actualizar. Probá de nuevo.' });
  } finally { clearTimeout(t); }
}

// Vista: función del estado, con el esqueleto armado una sola vez
const raiz = document.getElementById('raiz');
raiz.innerHTML = `<main>
  <header><h1>Pedido AR-1042</h1><button type="button" id="act">Actualizar</button></header>
  <section class="tarjeta" aria-labelledby="estado-t">
    <h2 id="estado-t">Estado</h2>
    <p id="estado" role="status">Cargando…</p>
    <div class="barra" aria-hidden="true"><span id="avance"></span></div>
    <ol id="paradas"></ol>
  </section></main>`;
const $ = id => document.getElementById(id);
function pintar() {
  const { cargando, error, pedido } = estado;
  $('estado').textContent = error ?? (cargando ? 'Cargando…'
    : `En camino: parada ${pedido.parada} de ${pedido.de}`);
  if (!pedido) return;
  $('avance').style.setProperty('--avance', pedido.parada / pedido.de);
  const lis = $('paradas').children;
  pedido.paradas.forEach((p, i) => {
    let li = lis[i]; if (!li) { li = document.createElement('li'); $('paradas').append(li); }
    if (li.textContent !== p) li.textContent = p;
    const act = i + 1 === pedido.parada;
    if (act) li.setAttribute('aria-current', 'step'); else li.removeAttribute('aria-current');
  });
}
oyentes.add(pintar);
$('act').addEventListener('click', traerPedido);
performance.mark('esqueleto');
traerPedido().then(() => performance.mark('datos'));
